const input = $input.first().json;
const b64 = input.body?.photo_base64 || input.photo_base64 || '';

if (!b64) {
  return [{json: {text: 'Фото не получено.', animation: {}}}];
}

// Call coral-vision /detect_b64 (accepts JSON with base64)
let result;
try {
  result = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://127.0.0.1:8090/detect_b64?lang=ru&threshold=0.3',
    body: JSON.stringify({image: b64}),
    headers: {'Content-Type': 'application/json'},
  });
  if (typeof result === 'string') result = JSON.parse(result);
} catch (e) {
  return [{json: {text: 'Ошибка распознавания: ' + e.message, animation: {}}}];
}

const objects = (result.objects || []).filter(o => o.score > 0.4);
const seen = new Set();
const labels = [];
for (const obj of objects) {
  if (!seen.has(obj.label)) {
    seen.add(obj.label);
    labels.push(obj.label);
  }
}

let text, animation = {};
if (labels.length === 1) {
  text = 'Я вижу ' + labels[0] + '!';
  animation = {post: 'interact_emotion_happy'};
} else if (labels.length > 1) {
  text = 'Я вижу: ' + labels.slice(0, -1).join(', ') + ' и ' + labels[labels.length - 1] + '!';
  animation = {post: 'interact_emotion_happy'};
} else {
  text = 'Хм, не могу разобрать что на фото.';
}

return [{json: {text, animation}}];

